"""Editorial proposals, not decided game design. User-facing copy is German."""
PAGES=[]
def add(key,title,group,layout,goal,problem,changes,keep,effort='Klein',limit='',source=''):
 PAGES.append(dict(id=key,title=title,group=group,layout=layout,goal=goal,problem=problem,changes=changes.split('|'),keep=keep,effort=effort,limit=limit,source=source))
I='mods/PLAYER/grug_inventory/pages.lua + ui.lua + navigation.lua'
C='mods/PLAYER/grug_jobs/ui.lua + details.lua + operation_box.lua + queue_box.lua'
T='mods/ENTITIES/grug_traders/trade.lua'
M='mods/PLAYER/grug_mail/window.lua'
add('inventory','Inventar','Charakter & Inventar','inventory','Gegenstände ordnen, Geld verwalten, Schnellzugriff bestücken.','Sortieren steht zwischen Geldaktionen; der leere Inventarbereich wirkt wie verlorener Platz. Die A/B-Wahl hängt winzig am Rand.','Sortieren direkt an die Inventarüberschrift: Wirkung und Auslöser gehören zusammen.|Geld, Einzahlung und Auto-Einzahlung als eigene Zeile unter dem Raster bündeln.|A/B neben die Hotbar-Überschrift setzen; Taschen und Trankgürtel sauber darüber ausrichten.','Alle nativen Slots, Taschenwachstum, Scrollbereich und Transfers bleiben erhalten.', 'Mittel','Die freie Rasterfläche ist Reserve für Taschen, kein Platz für eine neue Vorschau.',I)
for key,title,problem,change in [
 ('stats','Charakter · Werte','Einzelwerte, Gildenruf und Umhangwahl stehen ohne klare Abschnitte in einer langen Spalte.','Werte als ruhige Schlüssel/Wert-Zeilen setzen.|Kampfwerte, Gildenruf und Umhang sichtbar gruppieren; Heimkehr unter der Ausrüstung verankern.'),
 ('effects','Charakter · Effekte','Der Leerzustand beginnt abrupt am oberen Rand und erklärt die Ansicht nur als Textblock.','Leerzustand mit klarer Überschrift und kurzem Erklärungstext strukturieren.|Bei aktiven Effekten gleich hohe Zeilen mit bestehenden Icons und Texten verwenden; keine neue Effekt-Sonderbehandlung.'),
 ('achievements','Charakter · Erfolge','Fortschritt klebt am Namen; Beschreibung und Kategorie haben kaum optische Ordnung.','Name und Fortschritt an zwei festen Kanten ausrichten.|Beschreibung unmittelbar darunter; Pagination mittig an den Listenfuß setzen.')]:
 add(key,title,'Charakter & Inventar','character','Ausrüstung und '+{'stats':'Werte','effects':'aktive Effekte','achievements':'Erfolge'}[key]+' schnell erfassen.',problem,change+'|Ausrüstung und Modell bleiben an derselben Position beim Untertabwechsel.','Stats / Effects / Achievements, Modell, Umhang, Heimkehr, gegebenenfalls Köcher und Inventar bleiben.','Klein','Kein zusätzlicher Effekt-Countdown; Text und Status kommen weiterhin aus dem bestehenden Renderer.',I)
add('talents','Talente & Skills','Charakter & Inventar','talents','Punkte verteilen und Skills auf die Hotbar ziehen.','Baum, Punktestand und Skill-Reihe wirken wie lose aneinandergehängte Flächen. Die kleine Anleitung ist leicht zu übersehen.','Baumauswahl links und Punktestand rechts in einer gemeinsamen Kopfzeile.|Originalbaum samt Hintergrund und Verbindungen unberührt in einem klaren Bereich halten.|Skills als beschriftete native Leiste mit eigener Höhe direkt darunter; Respec räumlich vom Punktestand trennen.','Alle Klassenbäume, Voraussetzungen, Kauf pro Klick, Respec-Bestätigung und Skill-Drag bleiben.','Mittel','Der Baum im Entwurf ist ein Ausschnitt der echten Aufnahme, kein neu erfundener vereinfachter Baum.','mods/PLAYER/grug_classes/talents_ui.lua + talent_graph_ui.lua; grug_skills/page.lua')
add('party','Party & PvP','Charakter & Inventar','party','Mitspieler finden, Gruppe verwalten, PvP bewusst schalten.','Vier gleich gewichtete Kästen mischen Gruppensuche, Einladungen, Gruppe und PvP; der gefährlichere PvP-Schalter wirkt beiläufig.','Links Gruppenmitglieder und Einladen zusammenführen; Einladungen darunter mit ihren Aktionen.|Rechts PvP-Status, Folgen und Schalter als eigenen Bereich; Statistiken darunter.|HUD-Optionen in eine beschriftete Zeile an den Seitenanfang.','Solo-, Mitglied- und Leiterrechte, Refresh, Kick/Leave, Einladungen und PvP-Regeln bleiben.','Mittel','Keine neue Gruppensuche oder automatische Aktualisierung. Die Vorschau zeigt den Solozustand.','mods/PLAYER/grug_parties/ui.lua; grug_pvp/page.lua')
for key,title,problem,changes in [
 ('crafting','Crafting · Übersicht','Die leere rechte Hälfte erklärt Berufe, während die eigentliche Arbeitsrichtung unklar bleibt.','Berufsübersicht mit eindeutiger Aufforderung zur Rezeptauswahl.|Tier und Fortschritt direkt dem Beruf zuordnen; Queue-Status bleibt am Fuß der Arbeitsfläche.'),
 ('craft_details','Crafting · Zutaten & Quellen','Quellenkarten sind sehr hoch; Zutatenname, Besitz und Bezugsquelle konkurrieren um Aufmerksamkeit.','Pro Zutat eine kompakte Kopfzeile: Icon, Name, benötigte Menge, Besitz.|Quellen kleiner, aber gut lesbar darunter; Kinds auf derselben Zeile wie die passende Zutat.'),
 ('craft_group','Crafting · Zutatenalternativen','Der zweite Zurück- und Seitenwechselbereich ist optisch kaum von der Rezeptliste links getrennt.','Eindeutiger Titel „Kinds of …“ mit Back davor.|Alternativen als gleich hohe Zeilen; deren Pagination bleibt ausschließlich unter dieser Liste.'),
 ('craft_queue','Crafting · Warteschlange','„No job running“ erscheint zweimal, während der Zusammenhang mit den fünf Plätzen wenig greifbar ist.','Eine Statuszusammenfassung für die Queue statt zwei gleich lauter Leerhinweise.|Die vorhandenen fünf Jobs als geordnete Liste; bestehende Abbruchaktionen nur am jeweiligen Job.'),
 ('craft_enchant','Crafting · Verzaubern','Zielslot und spätere Aktion liegen weit auseinander; der Leerzustand nutzt sehr viel unbeschriftete Fläche.','Ziel, Ergebnis und Hinweis in einer gemeinsamen Arbeitszeile.|Vorhandene Verzauberungsauswahl darunter; Kosten und Aktion unmittelbar darunter bündeln.'),
 ('craft_upgrade','Crafting · Aufwerten','Die lose Upgrade-Schaltfläche unten rechts hat im Leerzustand wenig sichtbaren Bezug zum Zielslot.','Zielslot, aktuelle Stufe und mögliches Ergebnis zusammenstellen.|Bedingungen und Kosten direkt über dem vorhandenen Upgrade-Button; im Leerzustand eine klare Anleitung.')]:
 add(key,title,'Crafting','craft', 'Beruf → Rezept oder Operation → Ergebnis nachvollziehen.',problem,changes+'|Suchfeld und Filter bleiben links; Rezept-Pagination an dessen Fuß. Liste und Details bekommen dieselbe Grundschrift.', 'Fünf Berufsbereiche, Favoriten, Filter, Details-Navigation, Ziel-/Ergebnislisten, Mengen und Queue bleiben.', 'Mittel','Keine neuen Countdown- oder Prozentanzeigen. Animierte Fortschritte und vorhandene Sendetakte bleiben. Die Detailansicht erhält keinen neuen Craft-Button.',C)
for key,title in [('map','Map & Quests'),('map_zones','Map & Quests · Zonen')]:
 add(key,title,'Karte & Quests','map','Ort und Questkontext gleichzeitig verstehen.','Die Karte nutzt die linke Hälfte nicht ganz; Layer, Zoom und Rückkehraktionen bilden mehrere konkurrierende Zeilen.' if key=='map' else 'Zonenbeschriftungen sind trotz 2×-Einstieg dicht. Zusätzliche Bedienelemente dürfen der Karte nicht noch mehr Platz nehmen.', 'Zwei gleich breite Bereiche, aber Karte proportional in ihrer Hälfte: keine Streckung auf 1:1.|Zoom an den Kartenkopf, alle acht Layer kompakt direkt darunter; native Scrollbalken bleiben am Kartenrand.|Questliste oben rechts, ausgewählter Text darunter; Track und Abandon dem Questdetail zuordnen.', '50/50-Aufteilung, 9:8-Karte, acht Layer, keine automatische Questauswahl, HUD-Schalter und bestehende Abandon-Bestätigung bleiben.', 'Mittel','Die Zonenkarte kombiniert archivierte Testwelt-Kartenkunst mit separaten HTML-Labels aus dem korrigierten Formspec-Beleg. Browser-Zoom zeigt die Flächennutzung, nicht Luantis genaue Schriftmetriken oder einen aktuellen Weltstand. Kein neuer Zoom-/Clustering-Algorithmus.','mods/PLAYER/grug_map/window.lua + quest_box.lua + layers.lua + zone_labels.lua')
add('quest','Questgeber','Karte & Quests','quest','Angebot verstehen und Belohnung bewusst auswählen.','Zwei unabhängig scrollende Textflächen und kleine Reward-Icons zerlegen den Lesefluss. Accept und Close sind ähnlich betont.','Links Statusgruppen und Questliste, rechts zuerst Titel und Gespräch, dann Ziele und Belohnungen.|Belohnungsauswahl mit fester Zeile und ruhigem Hintergrund direkt oberhalb der Aktion.|Accept/Complete rechts betonen, Close links; gesperrte Zustände an derselben Stelle erklären.','Vollständiger Questtext, verfügbare/aktive/fertige/gesperrte Quests, fixe und wählbare Rewards sowie heutige Bestätigungen bleiben.','Mittel','Native Textflächen dürfen scrollen. Keine neue Quest-Zwischenseite, keine automatische Wahl einer Belohnung.','mods/PLAYER/grug_quests/npc.lua')
for key,title,problem,change in [
 ('vendor','Händler · Allgemein','Zwei Kartenspalten verteilen Preise und Buy-Buttons auf viele kleine Blickziele.','Eine kompakte Tabelle mit festen Spalten für Gegenstand, Preis und Buy; gleicher Klickweg, längere Namen haben Platz.'),
 ('vendor_gear','Händler · Ausrüstung','Lange Ausrüstungsnamen stoßen in schmalen Karten schnell an Grenzen.','Dieselbe einspaltige Angebotstabelle wie General; Tooltip bleibt für volle Werte, ohne neue Item-Vorschau.'),
 ('vendor_sell','Händler · Verkaufen','„1“ und „All“ sind ohne klare Spaltenüberschriften leicht zu verwechseln; Losgrößen stehen mitten im Text.','Besitz und Los-/Stückpreis als feste Spalten; Einzeln und Gesamtsumme rechts zusammenhalten.'),
 ('vendor_exchange','Gildenhändler · Trade-in','Geld, Rufguthaben und lebenslanger Fortschritt konkurrieren um Aufmerksamkeit.','Rufguthaben und Rang als klare Zusammenfassung; Tauschrate und abgebbare Menge in einer lesbaren Tabelle.'),
 ('vendor_guild','Gildenhändler · Rufangebote','Zwei Effektreihen und viele graue Zustände ergeben ein schwer lesbares Gitter.','Je Rang eine klar abgegrenzte Zeile mit beiden bestehenden Angeboten; Kauf und Freischaltgrund an festen Positionen.')]:
 add(key,title,'Handel & Dienste','vendor','Angebot, Kosten und verfügbare Aktion in einem Blick erfassen.',problem,change+'|Buy / Sell / Trade-in bleiben oben; Geld oder Ruf und eventueller Rabatt direkt darunter.|Icons klein und einheitlich; nur aktive Aktionen betonen, Sperrgründe lesbar statt fast unsichtbar.', 'Keine Warenkörbe, neuen Mengenregler oder Bestätigungen. Alle Angebote, Los-/Restmengenregeln und heutigen Verkaufsquellen bleiben.', 'Mittel','Einspaltiger Kauf braucht mehr vertikales Scrollen, gewinnt dafür eindeutige Preis-/Buttonspalten. Gildenrang und Ausgabeleistung bleiben getrennt.',T+'; mods/PLAYER/grug_guild/vendor.lua + exchange.lua')
add('repair','Reparatur','Handel & Dienste','repair','Einzelne oder alle beschädigten Gegenstände reparieren.','Bei wenigen Einträgen ist zwischen dem Gegenstand und „Repair all“ fast ein ganzes leeres Fenster.','Namens-, Haltbarkeits- und Preisspalten ausrichten.|Repair all und Gesamtkosten direkt unter der Liste zusammenfassen; Pagination dort mittig.|Kompakte feste Servicegröße statt unnötig großer Leerfläche.','Einzel-/Gesamtreparatur, vorhandene Quote, Seiten und Prüfung veralteter Preise bleiben.','Klein','Haltbarkeit ist eine bestehende Momentaufnahme, kein neuer periodischer Fortschritt.','mods/ITEMS/grug_repair/providers.lua')
add('crown','Crownbinder','Handel & Dienste','crown','Kosten und Aufwertung vor dem Anwenden verstehen.','Gebühr, Geld und benötigte Krone stehen in engem Fließtext über einer fast leeren Liste.','Gebühr und Fallen Crown in einer eigenen Kostenzeile.|Gegenstand und „heutige Stufe → neue Stufe“ pro Zeile; Crown direkt daneben.|Leere Liste bekommt einen erklärenden Zustand, Seitenwechsel bleibt unten.','Sechs Einträge pro Seite, feste Kostenformel, Eligibility und sofortige vorhandene Anwendung bleiben.','Klein','Keine neue Vorschau- oder Bestätigungsmechanik. Zahlen im Entwurf sind aus dem Testzustand.','mods/ENTITIES/grug_traders/crown.lua')
for key,title in [('profession','Berufstrainer'),('alchemy','Alchemietrainer')]:
 add(key,title,'Handel & Dienste','trainer','Lernstatus erkennen und eine bewusste Berufsentscheidung treffen.','Begrüßung, Status und Regelhinweis sehen fast gleich aus. Unlearn steht an derselben Stelle wie eine positive Lernaktion.','Begrüßung oben, eigener Statusblock darunter.|Lernaktion rechts im Footer; Unlearn klar als destruktive Aktion links und nur im passenden Zustand.|Alchemy als zusätzlicher Beruf eindeutig beschriften, ohne primären Slotverbrauch zu suggerieren.','Voraussetzungen, zwei Primärberufe plus Alchemy, tatsächliche Begrüßung und bestehende Unlearn-Bestätigung bleiben.','Klein','Die Vorschau zeigt den aufgenommenen Zustand: Weaponsmith gelernt, Alchemy noch nicht.','mods/PLAYER/grug_jobs/trainers.lua')
for key,title in [('riding','Riding Trainer'),('shipwright','Shipwright')]:
 add(key,title,'Handel & Dienste','mount','Nächste verfügbare Stufe und deren Kosten verstehen.','Name/Level und Sperrgrund sind sehr klein; der freie Bereich trennt Kauf und Bedienhinweis unnötig weit.','Gleiche Zeilen für Stufe, Mindestlevel und Kauf/Zustand.|Owned, Vorgängerstufe und Mindestlevel als Text, nicht nur durch graue Farbe.|Fenster an die Zeilenzahl der Dienstfamilie anpassen, Close am gemeinsamen Footer.','Alle Stufen, Preise, Besitz- und Vorgängerregeln, Faktion/Reichweite und Quickbar-Verwendung bleiben.','Klein','Keine neuen Mount-Modelle, kein Preview-Karussell und keine zusätzlichen Kaufklicks.','mods/PLAYER/grug_mounts/trainer.lua')
for key,title,problem,change in [
 ('innkeeper','Innkeeper','Für einen einfachen Status ist die innere Karte übergroß; die eigentliche Aussage ist unten versteckt.','Ort als Titel, aktueller Heimatstatus direkt darunter; bestehende Bind-Aktion nur bei anderem Heimatort.'),
 ('waystone','Waystone','Zielnamen und „Not yet visited“ sind nur durch viel Leerraum verbunden.','Feste Spalten Ziel / Status / Travel; aktueller Ort bekommt eine klare, ruhige Markierung.'),
 ('lift','Gildenlift','Level-Nummer und negative Tiefe sind dicht zusammengedrängt; jede Zeile wirkt wie ein eigener kleiner Buttonkasten.','Etage und Tiefe separat ausrichten; aktueller Standort als Text, Travel nur an erreichbaren Zielen.')]:
 add(key,title,'Reise & Wohnen','travel','Ziel und Verfügbarkeit vor der Reise erkennen.',problem,change+'|Alle Zeilen gleich hoch, Schließen am unteren Rand; keine leere zweite Spalte ohne Aufgabe.','Alle aktuellen Ziele, Claim-Ziel, Fraktions-/Reichweiten-/Reiseprüfungen und bestehende Sofortaktion bleiben.','Klein','Kein neuer Reisebestätigungsschritt, keine neue Suche oder automatische Zielwahl.','mods/PLAYER/grug_home/innkeeper.lua + waypoints.lua; grug_guild/lift.lua')
add('housing','Housing Steward','Reise & Wohnen','housing','Voraussetzungen und die Claim-Stone-Nutzung verstehen.','Zwei schmale Textkästen erschweren das Lesen der wichtigen Aktivierungs- und Brennstoffregeln.','Ein breiter, klar gegliederter Regelbereich: erhalten → platzieren/aktivieren → versorgen.|Alle bestehenden Hinweise bleiben; Gebühren und Fristen stehen bei ihrem Schritt.|Receive Claim Stone unten rechts, Close links; Refusals unmittelbar über der Aktion.','Level-, Gebiets-, Aktivierungs-, Brennstoff- und Wiederherstellungsregeln bleiben unverändert.','Klein','Kein interaktiver Assistent und keine zusätzliche Seite.','mods/PLAYER/grug_housing/manager.lua')
for key,title,problem,change in [
 ('claim','Claim Stone · Verwaltung','Brennstoff, Zugriffsrechte und Pick up/Set home stehen dicht beieinander, obwohl sie verschiedene Risiken haben.','Oben Brennstoff und Schutzstatus, darunter Berechtigungen mit zugehörigem Namensfeld.|Remove access direkt zur Liste; Pick up stone separat am Footer, Set as home daneben mit Abstand.'),
 ('claim_travel','Claim Stone · Waypoints','Beim Tabwechsel schrumpft das Fenster stark; Navigation und Close springen.','Gemeinsame Mindestbreite und stabiler Tabkopf für die Claim-Familie.|Reiseziele in festen Zeilen; freie Fläche bleibt bewusst ruhig statt erfundener Zusatzfunktionen.'),
 ('claim_belongings','Claim Stone · Belongings','Der Hinweis zum Auspacken ist von den übernommenen Gegenständen nur schwach getrennt.','Recovered-Inventar und heutiges Spielerinventar klar beschriften.|Den bestehenden Auspackhinweis unmittelbar an die Take-only-Slots setzen, Close aus der Transferzone nehmen.')]:
 add(key,title,'Reise & Wohnen','claim','Claim-Aufgaben mit eindeutigem Kontext erledigen.',problem,change,'Aktivierung/Draft, Eigentümerrechte, Brennstoffslot, Berechtigungen, Pickup-Bestätigung und Take-only-Wiederherstellung bleiben.','Mittel','Keine neue gemeinsame Speicherung; die Claim-Tabs bleiben dieselben. Höhe darf zwischen Reise und Inventar variieren, Kopfposition soll stabil bleiben.','mods/PLAYER/grug_housing/stone_form.lua')
for key,title in [('chest','Kiste'),('locked_chest','Abgeschlossene Kiste'),('bookshelf','Bücherregal'),('vessels','Gefäßregal')]:
 add(key,title,'Container & Stationen','container','Gegenstände zwischen Behälter und Inventar bewegen.','Der Grundaufbau funktioniert bereits. Überschriften und A/B-Wahl sind lediglich klein; bei Kisten ist der Schlosskontext kaum erkennbar.','Behältertyp als lesbaren Titel setzen, beim Locked Chest den Typ ausdrücklich nennen.|Behälter und Spielerinventar mit einer klaren Trennlinie statt weiteren Karten trennen.|Hotbar-Beschriftung und A/B gemeinsam ausrichten.','Exakte Slotanzahl, native Listen, Inhaltseinschränkungen, Schloss/Schutz und Shift-Klick bleiben.','Klein','Keine Sortier-, Take-all- oder Suchfunktion ergänzen.','mods/BASE/default/chests.lua + nodes.lua; vessels/init.lua; mods/PLAYER/grug_inventory/ui.lua')
for key,title in [('furnace','Ofen · gemeinsam'),('dual_furnace','Doppelofen · gemeinsam'),('personal_furnace','Ofen · persönlicher Arbeitsplatz'),('personal_dual_furnace','Doppelofen · persönlicher Arbeitsplatz')]:
 add(key,title,'Container & Stationen','furnace','Input, Brennstoff und fertige Ergebnisse eindeutig zuordnen.','Die Brennstoffflamme liegt optisch lose unter dem Slot; privat/gemeinsam ist nur eine kleine Textzeile.','Input links, Prozess mit Brennstoff mittig, Output rechts; alle Slots auf einem gemeinsamen Raster.|Flamme und animierten Prozessindikator dem Brennstoff/Prozessbereich direkt zuordnen.|Privat bzw. gemeinsam unmittelbar unter dem Titel lesbar kennzeichnen.','Alle Input-/Fuel-/Output-Listen und Kapazitäten, privater Workspace oder echte gemeinsame Node-Liste bleiben.','Klein','Kein Prozentwert und kein Countdown; vorhandene Animationen, Stau-/Leerlaufzustände und Update-Takte bleiben.','mods/BASE/default/furnace.lua; mods/PLAYER/grug_jobs/workspaces.lua; mods/ITEMS/grug_smelting/node.lua')
for key,title,problem,change in [
 ('mail_letters','Mailbox · Briefe','Die Listenzeilen sind extrem klein; Löschaktion und Anhänge wirken vom eigentlichen Brief abgetrennt.','Liste etwa 38 %, Lesebereich 62 %; kurze Listeinträge mit vollem Betreff im Detailkopf.|Anhänge und Take all direkt unter dem Brief, Delete in einer separaten Fußzeile.'),
 ('mail_announcements','Mailbox · Ankündigungen','Der Leerzustand ist ein winziger Satz in einer sehr großen Fläche.','Titel, kurze Leermeldung und Herkunft sauber gruppieren.|Bei vorhandenen Ankündigungen dasselbe Listen-/Leseraster wie bei Briefen benutzen.'),
 ('mail_write','Mailbox · Brief schreiben','Die große Nachrichtfläche und Porto-/Anhangshinweise haben keine klare abschließende Aktionsgruppe.','Empfänger und Betreff in eine gemeinsame Kopfzeile, Nachricht darunter in voller Breite.|Vier Anhangsslots links, Porto rechts; Send und Discard gemeinsam im Footer, Inventar darunter.'),
 ('mail_admin','Mailbox · An die Administration','Formular und Verlauf stehen gleich breit nebeneinander, obwohl der leere Verlauf kaum Platz braucht.','Schreiben links mit ca. 60 %, Verlauf rechts mit ca. 40 %.|Topic, Subject, Message vertikal ordnen; kostenlose Send-Aktion direkt unter dem Text.'),
 ('mail_delete','Mailbox · Löschbestätigung','Die Warnbox sitzt klein unter den Anhängen; die Konsequenz fällt leicht unter den Tisch.','Bestehende Warnung im Detailbereich breiter darstellen.|Cancel zuerst und neutral, Delete deutlich als Gefahr; Anhänge bleiben direkt darüber sichtbar.')]:
 add(key,title,'Post & Administration','mail','Briefe lesen oder versenden, Anhänge bewusst behandeln.',problem,change+'|Tabtitel dürfen zweizeilig angeordnet werden, statt bei GUI 1,5 zu überlappen.', 'Brief-/Announcement-Rechte, Entwürfe, Anhangsslots, Porto, Löschfristen und bestehende Bestätigungen bleiben.', 'Mittel','To the admin ist ein Spielerformular. Keine neuen Brief-Icons, Suchfunktionen oder zusätzlichen Sendeschritte.',M)
for key,title in [('admin_mail','Admin Mail · Übersicht'),('admin_compose','Admin Mail · Schreiben')]:
 add(key,title,'Post & Administration','admin','Anfragen bearbeiten oder einen Adminbrief verfassen.','Der leere Listenbereich dominiert die Übersicht.' if key=='admin_mail' else 'Empfänger, Nachricht, Vorschau und Hinweise sind auf engem Raum gestapelt; bei GUI 1,5 kollidieren Beschriftungen.', 'Open / All / Announcements als klare lokale Navigation; New admin letter rechts.' if key=='admin_mail' else 'Empfänger und All players zusammen; dann Betreff und Nachricht. Vorschau erhält einen klaren eigenen Bereich.', 'mail_admin-Prüfung, Open/All/Announcements, Antworten/Schließen/Löschen, Vorschau und direktes Senden bzw. Löschen von Ankündigungen bleiben.', 'Mittel','Keine automatische Live-Vorschau: Update preview bleibt explizit. Text-only, keine Anhänge.', 'mods/PLAYER/grug_mail/admin.lua')
for key,title in [('creative_all','Creative · All'),('creative_nodes','Creative · Nodes'),('creative_tools','Creative · Tools'),('creative_craftitems','Creative · Items'),('creative_food','Creative · Food')]:
 add(key,title,'Creative & Werkzeuge','creative','Gegenstände suchen und in das eigene Inventar übernehmen.','Suchfeld und Pagination liegen unter dem Raster; der Papierkorb steht mitten in dieser Navigationszeile.','Suche und Reset direkt über das native Katalograster.|Pagination allein unter dem Raster; Trash als eigenes beschriftetes natives Feld daneben.|Creative bleibt in der Hauptnavigation; alle fünf Kategorien stehen gemeinsam in einer zweiten Leiste.','Creative-Zugriff, alle Kategorien, originale 8×4-Katalogliste, Inbox, Trash und Transfers bleiben.','Klein','Trash bleibt ein Slot, kein neuer Löschbutton; keine neue Kategorie-Datenstruktur.','mods/BASE/creative/inventory.lua; mods/PLAYER/grug_inventory/ui.lua')
for key,title,problem,change in [
 ('sign','Schild bearbeiten','Ein kleines grünes Eingabefeld und Save lassen Fokus und eigentliche Aufgabe kaum voneinander unterscheiden.','Titel und Feldlabel trennen; neutraler Feldhintergrund mit klarer Fokuslinie; Save unten rechts.'),
 ('book','Buch · Lesen / Schreiben','Das große graue Textfeld wirkt wie ein Fremdkörper, Titel und Modusauswahl sind sehr eng.','Write / Read in einen ruhigen Tabkopf; Titel oberhalb des Textfelds, Save im Footer.|Lesemodus behält seine Seitenkontrolle und berechtigungsabhängige Bearbeitung.'),
 ('mob_spawner','Mob Spawner','Die Parameterbeschreibung steht als lange Klammerkette über einem einzelnen Kommando; das ist schlecht zu überblicken.','Das vorhandene Kommando als ein einziges Monospace-Feld erhalten.|Parameterschema in zwei lesbare Zeilen darunter, Done rechts. Keine neue Parseroberfläche.'),
 ('mob_texture','Mob Texture','Die technische Zeichenkette wird wie gewöhnlicher Fließtext dargestellt; der Kontext der Änderung bleibt vage.','Texturfeld mit Monospace, gut erkennbarem Fokus und lesbarer Breite.|Change direkt darunter rechts; keine falsche Behauptung einer zusätzlichen Privilegienprüfung.')]:
 add(key,title,'Creative & Werkzeuge','editor','Bestehende Eingabe sicher lesen und gezielt speichern.',problem,change, 'Originalfelder, Parser, Eigentums-/Schutzprüfungen, Save/Done/Change und heutige Close-Regeln bleiben.', 'Klein','Keine Syntaxprüfung oder neuen Dateibrowser hinzufügen. Diese Werkzeugfenster sind nicht pauschal admin-only.', 'mods/BASE/default/nodes.lua + craftitems.lua; mods/ENTITIES/mobs/spawner.lua + crafts.lua')
for key,title,problem,change in [
 ('creation','Charakter erstellen','Die Entscheidungen laufen quer durch das Fenster; Modellauswahl und finaler Button wirken an den Rand gedrängt.','Eine Seite: Fraktion oben, Race links, Class rechts, Appearance darunter.|Finalitäts-Hinweis unmittelbar vor Create character; kein Schritt-Assistent.'),
 ('preparing','Ankunft vorbereiten','Die Prozentzahl steckt im Satz; Status, Restzeitschätzung und Rückkehrhinweis haben kaum Abstufung.','Statusüberschrift, bestehende Prozentzahl rechts, statischer Balken direkt darunter.|Vorhandene Schätzung und Disconnect-Hinweis als sekundäre Zeilen; Ready/Retry bleibt derselbe Zustand.'),
 ('welcome','Willkommen','Viele gleich starke Linkbuttons konkurrieren mit „Got it“; die zwei Textspalten wirken wie gleich große Pflichtblöcke.','Bestehende sechs Tipps als kurze Abschnitte in einem scrollbaren Lesebereich.|Links in eine eigene ruhige Zeile; Got it allein als Hauptaktion rechts unten.'),
 ('quickbar','Schnellleiste','Die vier Bereiche sind bereits sinnvoll, aber Überschriften und Status sind zu eng.','Gleiche vertikale Abstände für Mounts, Potion belt, Active Hotbar und Home.|A/B gleich breit; Return home mit Status direkt im eigenen Abschnitt.'),
 ('withdraw','Münzen abheben','Die Struktur ist schon gut; Hauptaktion und Cancel stehen jedoch entgegen dem vorgeschlagenen gemeinsamen Muster.','Drei Felder weiter in einer Zeile mit klaren Gold/Silver/Copper-Labels.|Balance oben, Bag-of-Coins-Hinweis darunter; Cancel links, Withdraw rechts.')]:
 add(key,title,'Start & Schnellzugriff',key,'Die jeweilige Hauptaufgabe ohne unnötige Nebenwege erledigen.',problem,change,'Bestehende Felder, Speicherung erst bei Create, Zustände, Links und Aktionen bleiben.','Klein' if key!='creation' else 'Mittel','Quickbar-Klick benutzt und schließt; A/B hält offen. Preparing verwendet bestehende Prozentwerte, keine neue Animation. Keine zusätzliche Erstellungsseite.' if key in ['quickbar','preparing','creation'] else 'Keine neue Funktion und keine neuen Statusupdates.', 'mods/PLAYER/grug_classes/selection.lua; grug_visuals/creation.lua; grug_inventory/welcome.lua; grug_quickbar/init.lua; grug_money/coins.lua')
for key,title,focus in [('help_start','Hilfe · Start','erste Schritte, Tasten und Level'),('help_quests','Hilfe · Quests & Professions','Quests und Berufe'),('help_basics','Hilfe · Basics','Erze und Tiefen'),('help_mail','Hilfe · Mail','Briefe und Admin-Kontakt'),('help_formulas','Hilfe · Formeln','Formeln und ihre Erklärung'),('help_about','Hilfe · About','Version und externe Links'),('help_sound','Hilfe · Sound','Musik und Umgebung')]:
 add(key,title,'Hilfe','help','Informationen zu '+focus+' schnell finden.','Sieben lokale Tabs konkurrieren mit den Haupttabs; lange Zeilen und kleine Zwischenüberschriften erschweren das Querlesen.','Hilfethemen links als schmale Liste, rechts die ausgewählte Seite: zwei Navigationsebenen sind klar getrennt.|Bestehende Abschnitte durch Abstände und lesbare Titel gliedern, den vollständigen Text in einer nativen Scrollfläche behalten.|'+('Schalter und Volume-Dropdown pro Zeile ausrichten; Erklärung darunter.' if key=='help_sound' else 'Links mit ihrer Aufgabe beschriften und die vorhandenen URL-Felder behalten.' if key=='help_about' else 'Keine neuen aufklappbaren Untermenüs: ein Klick wählt weiterhin genau ein Hilfethema.'),'Alle sieben Themen, vollständige Texte, URL-Aktionen, Lautstärkedropdowns und Schalter bleiben.','Mittel','Die Grafik zeigt einen gekennzeichneten Textauszug. Die Umsetzung müsste den vollständigen vorhandenen Text übernehmen.','mods/PLAYER/grug_inventory/help.lua; mods/CORE/grug_ambience/init.lua')

# User feedback revision: distinguish preserved behavior from requested extensions.
revisions={
 'inventory':('Die erste Studie verkürzte das Inventar und ließ rechts ungenutzten Platz. Das war kein sinnvoller Tausch gegen größere Fenster.', ['Inventar links als hoher 8er-Rasterbereich; Geld, Einzahlung und Auto-Einzahlung rechts daneben.','Bags und Potion belt mit kurzem, identischem Labelabstand. Coin-Bag-Ghost bleibt.','Große Taschen: elf Reihen Gesamtinhalt zum Scrollen; keine Kapazitätserweiterung. Hotbar immer darunter mit kleinen A/B-Schaltern rechts.']),
 'quickbar':('Die erste Studie verlor die klickbaren Rahmen der Mounts und verwendete ungleiche Innenabstände.', ['Mounts und Boote behalten gerahmte Icon-Buttons; aktive Auswahl und Dismount bleiben eigene Zustände.','Alle vier Bereiche verwenden gleiche Innenabstände und denselben Abstand unter ihren Bedienelementen.','Active Hotbar bleibt beschriftet; A/B sind kompakt. Benutzen schließt, Umschalten hält offen.']),
 'craft_details':('Die erste Studie ließ Zutaten-Icons weg und zeigte Besitz und Quellen nicht durchgängig.', ['Originale Zutaten- und Ergebnis-Icons wieder zeigen, ohne die Textgrößen aufzublähen.','Name, Menge und Besitz auf derselben Kopfzeile; Quellen direkt darunter.','Kinds bleibt an der betreffenden Zutat; zwei Inventarzeilen plus feste Hotbar bleiben sichtbar.']),
 'map':('Die erste Studie verschenkte Kartenhöhe durch zwei Layerzeilen und einen redundanten Rückkehrbutton; Liste und Details waren unklar getrennt.', ['Alle acht Layer in einem Dropdown, zusammen mit Zoom und Show minimap im Kopf.','Karte und Quests 50/50; Questliste und Detailbereich durch eigene Flächen trennen.','Bei größerem Zoom den gesamten verfügbaren Kartenausschnitt nutzen; kein zusätzliches Letterboxing. Zurück über die Haupttabs.']),
 'map_zones':('Die erste Studie hatte dieselben Platzprobleme wie die Questkarte und enthielt noch die alte Beschriftungsgrafik.', ['Einzeilige HTML-Labels aus dem korrigierten Formspec-Beleg auf illustrativer, nativer Kartenkunst darstellen.','Keine zweizeilige Layerleiste; Dropdown spart Höhe. Karte bleibt mit Scrollen erreichbar.','Browser-Zoom illustriert den Ausschnitt; Luantis Schriftgrößen je Zoom bleiben ein späterer Client-Prüfpunkt.']),
 'repair':('Der Gesamtpreis stand in der ersten Studie vom Repair-all-Button getrennt und war dadurch leicht zu übersehen.', ['Repair all trägt den Gesamtpreis wieder direkt im Button.','Einzelpreis und Einzelreparatur bleiben am jeweiligen Gegenstand.','Kompakte Dienstgröße mit klarer Pagination und Abschlusszeile.']),
 'party':('Die erste Studie zeigte fast nur den Solozustand; dadurch blieb die aktuelle Gruppenansicht unklar.', ['Solo, Mitglied und Leiter im gleichen Layout direkt im Zustandswähler darstellen.','Klassen-Icon, Level, HP / Offline und Leitermarkierung pro Mitglied erhalten.','Leave für Mitglieder; Kick und Make leader nur für den Leiter bei einem anderen ausgewählten Mitglied.']),
}
for p in PAGES:
 if p['id'] in revisions:p['problem'],p['changes']=revisions[p['id']]
 if p['layout']=='craft':
  p['changes']+=['Rezeptliste behält jedes Icon und den ×N-Herstellbarkeitsindikator aus der gespeicherten Formspec. Blockgegenstände erscheinen als native 3D-Inventarbilder.']
 if p['layout']=='container':
  p['problem']='Die erste Studie verschwendete Höhe und entfernte die funktionalen Slot-Hinweise.'
  p['changes']=['Behälterraster dicht mit der Überschrift verbinden; freien Platz dem Spielerinventar geben.','Mehr sichtbare 8er-Inventarzeilen, mit elf Reihen Gesamtinhalt prüfbar; Scrollen und Transfers bleiben.','Bücher- und Gefäß-Ghosts bleiben in jedem dafür vorgesehenen Slot; gemeinsame Hotbar mit kleinen A/B-Schaltern rechts.']
 if p['id'] in ['vendor_sell','vendor_exchange']:
  p['changes']=['Eine Zeile pro Gegenstand: natives Itembild, Name, Besitz, Preis/Tauschrate und Mengenaktionen.','1 / 5 / 10 / All als ausdrücklich neue Bedienfunktion zeigen; inaktive Mengen bei zu kleinem Bestand.','Losgrößen und Restmengen erhalten; All zeigt weiterhin den Gesamterlös.']
  p['keep']='Preise, Losgrößen, Restmengen, Verkaufsquellen und Validierungen bleiben. Die zusätzlichen Mengenaktionen sind noch nicht implementiert.'
  p['limit']='Bewusste Funktionserweiterung: im Sell gibt es bisher 1/All nur bei Stückware, im Trade-in bisher nur All. Mengenbuttons benötigen validierte Serveraktionen, keine neue Wirtschaftsregel.'
 if p['layout']=='character':p['changes']+=['Alle acht Ausrüstungsslots behalten ihre Ghost-Icons; mindestens zwei Inventarzeilen und die identische Hotbar bleiben darunter.']
 if p['layout']=='map':p['keep']='50/50-Aufteilung, acht Layer, native Scrollbarkeit, HUD-Schalter, bestehende Abandon-Bestätigung und keine automatische Questauswahl. Der redundante Rückkehrbutton entfällt auf deinen Wunsch.'
